#include <atomic>
#include <chrono>
#include <csignal>
#include <cstdio>
#include <thread>

static std::atomic<bool> stop_requested{false};
static_assert(std::atomic<bool>::is_always_lock_free, "a signal handler may only touch lock-free atomics");

// The only thing the handler does is set a flag: anything else is unsafe here.
extern "C" void on_signal(int) { stop_requested.store(true); }

int main() {
  std::signal(SIGINT, on_signal);
  std::signal(SIGTERM, on_signal);
  int ticks = 0;
  while (!stop_requested.load()) {
    ++ticks;
    std::printf("tick %d\n", ticks);
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    if (ticks == 3) std::raise(SIGINT);  // stands in for Ctrl+C so the example stops on its own
  }
  std::printf("stopping after %d ticks\n", ticks);
  std::puts("saved");  // clean-up happens here, in normal code, not in the handler
  return 0;
}

void on_signal(int) {
  std::printf("stopping\n");  // not async-signal-safe: can deadlock inside printf
  save_everything();          // allocates and locks: the same problem
  std::exit(0);               // runs static destructors from inside the handler
}
